const grid=document.querySelector('#jobGrid');
function renderJobs(filter='all',query=''){
 let list=jobs.filter(j=>filter==='all'||(filter==='near'?j.distance<=1.6:filter==='highpay'?j.pay>=23:j.tags.includes(filter)));
 if(query){const q=query.toLowerCase();list=list.filter(j=>`${j.title}${j.merchant}${j.desc}`.toLowerCase().includes(q))}
 grid.innerHTML=list.length?list.map(j=>`<article class="job-card">${j.hot?`<span class="status-tag">${j.hot}</span>`:''}<div class="top"><span class="shop-icon ${j.tone}">${j.icon}</span><div><h3>${j.title}</h3><span class="merchant">${j.merchant}</span></div><span class="match-badge">${j.match}% 匹配</span></div><div class="job-meta"><span>◷ ${j.date} ${j.time}</span><span>⌖ 距你 ${j.distance}km</span><span>⚡ ${j.settle}</span><span>♙ ${j.people}</span></div><div class="job-bottom"><span class="pay"><b>¥${j.pay}</b><small>${j.unit||'/小时'}</small></span><button data-job="${j.id}">查看详情</button></div></article>`).join(''):`<div class="empty-state">没有找到相关岗位，换个关键词试试吧。</div>`;
}
renderJobs();
document.querySelectorAll('.slot-pills button').forEach(btn=>btn.onclick=()=>{document.querySelectorAll('.slot-pills button').forEach(b=>b.classList.remove('active'));btn.classList.add('active');renderJobs(btn.textContent.includes('周日')?'sunday':btn.textContent.includes('两天')?'all':'saturday');document.querySelector('#jobs').scrollIntoView({behavior:'smooth'})});
document.querySelectorAll('.category-card').forEach(btn=>btn.onclick=()=>{document.querySelectorAll('.category-card').forEach(b=>b.classList.remove('active'));btn.classList.add('active');const list=jobs.filter(j=>j.category===btn.dataset.category);grid.innerHTML=list.length?list.map(j=>`<article class="job-card">${j.hot?`<span class="status-tag">${j.hot}</span>`:''}<div class="top"><span class="shop-icon ${j.tone}">${j.icon}</span><div><h3>${j.title}</h3><span class="merchant">${j.merchant}</span></div><span class="match-badge">${j.match}% 匹配</span></div><div class="job-meta"><span>◷ ${j.date} ${j.time}</span><span>⌖ 距你 ${j.distance}km</span><span>⚡ ${j.settle}</span><span>♙ ${j.people}</span></div><div class="job-bottom"><span class="pay"><b>¥${j.pay}</b><small>${j.unit||'/小时'}</small></span><button data-job="${j.id}">查看详情</button></div></article>`).join(''):`<div class="empty-state">该类需求正在聚合中，先看看其他类别吧。</div>`;document.querySelector('#jobs').scrollIntoView({behavior:'smooth'})});
document.querySelectorAll('.filter').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.filter').forEach(b=>b.classList.remove('active'));btn.classList.add('active');renderJobs(btn.dataset.filter);}))
function scrollJobs(){document.querySelector('#jobs').scrollIntoView({behavior:'smooth'})}
document.querySelector('#announcementCta').onclick=scrollJobs;document.querySelector('#mobileJobs').onclick=scrollJobs;document.querySelector('#viewAll').onclick=()=>{document.querySelectorAll('.filter').forEach(b=>b.classList.remove('active'));document.querySelector('[data-filter="all"]').classList.add('active');renderJobs();showToast('已展示全部演示岗位')};
document.querySelectorAll('.quick-tags button').forEach(btn=>btn.onclick=()=>{document.querySelector('#heroSearch').value=btn.textContent;renderJobs('all',btn.textContent==='本周六'?'周六':btn.textContent);scrollJobs()});
document.querySelector('#heroSearchBtn').onclick=()=>{renderJobs('all',document.querySelector('#heroSearch').value.trim());scrollJobs()};
document.querySelector('#heroSearch').addEventListener('keydown',e=>{if(e.key==='Enter')document.querySelector('#heroSearchBtn').click()});
const backdrop=document.querySelector('#modalBackdrop'),jobModal=document.querySelector('#jobModal'),postModal=document.querySelector('#postModal');
function openModal(which){backdrop.hidden=false;jobModal.hidden=which!=='job';postModal.hidden=which!=='post';document.body.style.overflow='hidden'}
function closeModal(){backdrop.hidden=true;jobModal.hidden=true;postModal.hidden=true;document.body.style.overflow=''}
document.querySelectorAll('.modal-close').forEach(b=>b.onclick=closeModal);backdrop.addEventListener('click',e=>{if(e.target===backdrop)closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
grid.addEventListener('click',e=>{const id=Number(e.target.dataset.job);if(!id)return;const j=jobs.find(x=>x.id===id);document.querySelector('#jobModalContent').innerHTML=`<div class="modal-job-head"><span class="shop-icon ${j.tone}">${j.icon}</span><div><h2 id="modalTitle">${j.title}</h2><p>${j.merchant} · ${j.match}% 智能匹配</p></div></div><div class="modal-detail-grid"><div><small>工作时间</small><b>${j.date} ${j.time}</b></div><div><small>报酬</small><b>¥${j.pay}${j.unit||'/小时'}</b></div><div><small>通勤距离</small><b>${j.distance}km · 约 ${Math.round(j.distance*9)} 分钟</b></div><div><small>结算方式</small><b>${j.settle}</b></div></div><h3>工作说明</h3><p class="modal-description">${j.desc}</p><button class="apply-button" data-apply="${j.id}">使用学生档案一键报名</button>`;openModal('job')});
jobModal.addEventListener('click',e=>{if(e.target.dataset.apply){closeModal();showToast('报名成功！商家确认后会通知你 ✓')}});
document.querySelectorAll('[data-role]').forEach(btn=>btn.onclick=()=>{document.querySelectorAll('[data-role]').forEach(b=>b.classList.remove('active'));btn.classList.add('active');const merchant=btn.dataset.role==='merchant';document.querySelectorAll('.student-view').forEach(x=>x.hidden=merchant);document.querySelectorAll('.merchant-view').forEach(x=>x.hidden=!merchant);showToast(merchant?'已切换至商家端':'已切换至学生端')});
document.querySelector('#openPostJob').onclick=()=>openModal('post');document.querySelector('#mobilePost').onclick=()=>openModal('post');
document.querySelector('#postForm').onsubmit=e=>{e.preventDefault();closeModal();showToast('发布成功！AI 正在匹配附近学生 ✦');e.target.reset()};
document.querySelector('#startMatch').onclick=()=>{document.querySelector('#heroSearch').focus();window.scrollTo({top:0,behavior:'smooth'});showToast('告诉我们想找什么工作吧')};
document.querySelector('.mini-apply').onclick=()=>showToast('演示报名成功 ✓');document.querySelector('#trustDetails').onclick=()=>showToast('保障规则：实名审核、电子约定、工时确认、争议协助');
let toastTimer;function showToast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2600)}

